window.MedAssistPager = (() => {
  const transitionName = 'medassist-pager';
  const swipeBindings = new WeakMap();
  let current = null;
  let updating = false;
  let watchingResize = false;

  const reducedMotion = () => typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const activeTab = list => list?.querySelector('[aria-selected="true"],[aria-current="true"],.active');

  function indicatorPosition(list) {
    const selected = activeTab(list);
    if (!selected || !list.isConnected) return null;
    const bounds = selected.getBoundingClientRect();
    return {left: bounds.left - list.getBoundingClientRect().left + list.scrollLeft - list.clientLeft, width: bounds.width};
  }

  function decorateTabs(list) {
    if (!list?.isConnected) return;
    list.classList.add('pager-tabs');
    let indicator = list.querySelector(':scope > .pager-indicator');
    if (!indicator) {
      indicator = list.ownerDocument.createElement('span');
      indicator.className = 'pager-indicator';
      indicator.setAttribute('aria-hidden', 'true');
      list.append(indicator);
    }
    const position = indicatorPosition(list);
    indicator.hidden = !position;
    if (!position) return;
    const transitionList = updating && current && (list === current.tabList ||
      list === current.getTabList?.() || (current.tabListId && list.id === current.tabListId));
    const previous = transitionList && current.indicator;
    indicator.style.width = `${position.width}px`;
    indicator.style.transform = `translateX(${position.left}px)`;
    if (previous && !reducedMotion() && typeof indicator.animate === 'function') {
      current.indicator = null;
      current.indicatorAnimation = indicator.animate([
        {transform: `translateX(${previous.left}px)`, width: `${previous.width}px`},
        {transform: `translateX(${position.left}px)`, width: `${position.width}px`}
      ], {duration: 240, easing: 'cubic-bezier(.22,.61,.36,1)'});
    }
    const inset = 8;
    if (position.left < list.scrollLeft + inset) list.scrollLeft = Math.max(0, position.left - inset);
    else if (position.left + position.width > list.scrollLeft + list.clientWidth - inset) {
      list.scrollLeft = position.left + position.width - list.clientWidth + inset;
    }
    if (!watchingResize) {
      watchingResize = true;
      window.addEventListener('resize', () => {
        for (const tabs of list.ownerDocument.querySelectorAll('.pager-tabs')) decorateTabs(tabs);
      });
    }
  }

  function clean(record) {
    if (current !== record) return;
    for (const viewport of [record.before, record.after]) {
      if (viewport?.style.viewTransitionName === transitionName) viewport.style.viewTransitionName = '';
    }
    record.document?.documentElement.classList.remove('medassist-pager-transition');
    record.document?.documentElement.removeAttribute('data-pager-direction');
    current = null;
  }

  function invalidate() {
    if (updating || !current) return;
    const previous = current;
    previous.cancelled = true;
    previous.viewTransition?.skipTransition();
    previous.animation?.cancel();
    previous.indicatorAnimation?.cancel();
    clean(previous);
  }

  function transition({from = 0, to = 0, viewport, tabList, update, getViewport, getTabList, focus} = {}) {
    invalidate();
    if (typeof update !== 'function') return Promise.resolve(false);
    const record = {
      before: viewport,
      document: viewport?.ownerDocument,
      tabList,
      tabListId: tabList?.id,
      getTabList: typeof getTabList === 'function' ? getTabList : null,
      indicator: indicatorPosition(tabList),
      cancelled: false,
      applied: false
    };
    current = record;
    const direction = to < from ? -1 : 1;
    const animate = from !== to && !reducedMotion();

    const apply = () => {
      if (record.cancelled || current !== record) return;
      updating = true;
      try {
        update();
        record.applied = true;
        record.after = typeof getViewport === 'function' ? getViewport() : viewport;
        if (record.viewTransition && record.after?.isConnected) record.after.style.viewTransitionName = transitionName;
        decorateTabs(typeof getTabList === 'function' ? getTabList() : tabList);
        if (typeof focus === 'function') focus();
      } finally {
        updating = false;
      }
    };

    if (animate && viewport?.isConnected && typeof record.document.startViewTransition === 'function') {
      viewport.style.viewTransitionName = transitionName;
      record.document.documentElement.classList.add('medassist-pager-transition');
      record.document.documentElement.dataset.pagerDirection = direction > 0 ? 'next' : 'previous';
      record.viewTransition = record.document.startViewTransition(apply);
      // Skipping a transition rejects ready, while its guarded update still settles normally.
      record.viewTransition.ready.catch(() => {});
      record.viewTransition.finished.then(() => clean(record), () => clean(record));
      return record.viewTransition.updateCallbackDone.then(() => record.applied);
    }

    try {
      apply();
      if (animate && record.after?.isConnected && typeof record.after.animate === 'function') {
        record.animation = record.after.animate([
          {transform: `translateX(${direction * 48}px)`, opacity: .65},
          {transform: 'translateX(0)', opacity: 1}
        ], {duration: 220, easing: 'cubic-bezier(.22,.61,.36,1)'});
        record.animation.finished.then(() => clean(record), () => clean(record));
      } else clean(record);
    } catch (error) {
      clean(record);
      throw error;
    }
    return Promise.resolve(record.applied);
  }

  function bindSwipe(viewport, move) {
    if (!viewport || typeof move !== 'function') return;
    viewport.classList.add('pager-viewport');
    const existing = swipeBindings.get(viewport);
    if (existing) {
      existing.move = move;
      return;
    }
    const binding = {move, start: null};
    swipeBindings.set(viewport, binding);
    const selectionActive = () => {
      const selection = viewport.ownerDocument.getSelection();
      return selection && !selection.isCollapsed;
    };
    const blocked = target => viewport.ownerDocument.querySelector('dialog[open]') ||
      target?.closest?.('input,textarea,select,button,a,summary,label,dialog,[contenteditable]:not([contenteditable="false"]),[role="button"],[role="slider"],[role="textbox"],[role="tab"],[data-no-swipe],[draggable="true"]');

    viewport.addEventListener('pointerdown', event => {
      binding.start = null;
      if (!['touch', 'pen'].includes(event.pointerType) || event.isPrimary === false || event.button !== 0 || blocked(event.target) || selectionActive()) return;
      binding.start = {id: event.pointerId, x: event.clientX, y: event.clientY};
    }, {passive: true});
    viewport.addEventListener('pointermove', event => {
      const start = binding.start;
      if (!start || start.id !== event.pointerId) return;
      const dx = Math.abs(event.clientX - start.x);
      const dy = Math.abs(event.clientY - start.y);
      if (selectionActive() || (dy > 12 && dy > dx * .85)) {
        binding.start = null;
        return;
      }
      if (dx > 14 && dx > dy * 1.4 && event.cancelable) event.preventDefault();
    }, {passive: false});
    viewport.addEventListener('pointerup', event => {
      const start = binding.start;
      binding.start = null;
      if (!start || start.id !== event.pointerId || blocked(event.target) || selectionActive()) return;
      const dx = event.clientX - start.x;
      const dy = Math.abs(event.clientY - start.y);
      const threshold = Math.max(48, Math.min(96, viewport.clientWidth * .12));
      if (Math.abs(dx) >= threshold && dy <= Math.abs(dx) * .55) binding.move(dx < 0 ? 1 : -1);
    }, {passive: true});
    viewport.addEventListener('pointercancel', () => { binding.start = null; }, {passive: true});
  }

  return Object.freeze({transition, bindSwipe, decorateTabs, invalidate});
})();

window.MedAssistLabPaste = (() => {
  const MAX_TEXT_LENGTH = 20000;
  const MAX_ROWS = 100;
  const fields = ['name', 'result', 'unit', 'reference', 'note'];
  const headerAliases = new Map([
    ['показатель', 'name'], ['название', 'name'], ['название показателя', 'name'],
    ['исследование', 'name'], ['наименование', 'name'], ['наименование исследования', 'name'],
    ['результат', 'result'], ['значение', 'result'],
    ['ед', 'unit'], ['ед изм', 'unit'], ['единица', 'unit'], ['единицы', 'unit'],
    ['единица измерения', 'unit'], ['единицы измерения', 'unit'],
    ['норма', 'reference'], ['нормы', 'reference'], ['нормы из бланка', 'reference'],
    ['референс', 'reference'], ['референсные значения', 'reference'], ['референтные значения', 'reference'],
    ['референсный интервал', 'reference'], ['референтный интервал', 'reference'],
    ['примечание', 'note'], ['комментарий', 'note']
  ]);
  const numberSource = '[<>≤≥]?[ \\u00a0]*[+−-]?(?:\\d+(?:[.,]\\d+)?|[.,]\\d+)(?:[eE][+−-]?\\d+)?';
  const referenceMarker = /(?:^|[\s;]+)(?:норм(?:а|ы)?|референс(?:ные\s+значения|ный\s+интервал)?|референт(?:ные\s+значения|ный\s+интервал))(?=\s|[:=]|$)\s*[:=]?\s*/iu;

  function emptyRow(sourceLine, warning = '') {
    return {sourceLine, name: '', result: '', unit: '', reference: '', note: '', warnings: warning ? [warning] : []};
  }

  function columns(line) {
    if (line.includes('\t')) return {kind: 'tab', cells: line.split('\t')};
    if (line.includes('|')) return {kind: 'pipe', cells: line.split('|')};
    const referenceSuffix = line.indexOf(';');
    const simpleReference = referenceSuffix >= 0 && /\d/u.test(line.slice(0, referenceSuffix)) && /^;\s*(?:норм|референ|референт)/iu.test(line.slice(referenceSuffix));
    if (referenceSuffix >= 0 && !simpleReference) return {kind: 'semicolon', cells: line.split(';')};
    if (/\S[ \u00a0]{2,}\S/u.test(line)) return {kind: 'spaces', cells: line.trim().split(/[ \u00a0]{2,}/u)};
    return null;
  }

  function headerField(cell) {
    return headerAliases.get(cell.toLowerCase().replace(/ё/g, 'е').replace(/[.():]/g, ' ').replace(/\s+/g, ' ').trim());
  }

  function parseSimple(sourceLine) {
    const row = emptyRow(sourceLine);
    let line = sourceLine.trim();
    const reference = referenceMarker.exec(line);
    if (reference) {
      row.reference = line.slice(reference.index + reference[0].length).trim();
      line = line.slice(0, reference.index).trim();
      if (!row.reference) row.warnings.push('После обозначения нормы нет значения. Проверьте исходную строку.');
    }
    const pattern = new RegExp(`(?:\\s*:\\s*|\\s+)(${numberSource})(?=\\s|$)`, 'gu');
    const candidates = [];
    for (const match of line.matchAll(pattern)) {
      const name = line.slice(0, match.index).trim();
      const unit = line.slice(match.index + match[0].length).trim();
      if (!name || !/[a-zа-яё]/iu.test(name)) continue;
      const compactUnit = unit.replace(/\s*([/^×*·])\s*/gu, '$1');
      const scientificUnit = /^(?:10(?:\^[+−-]?\d+|[⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻]+)|(?:[a-zа-яёµμ]+))(?:[a-zа-яёµμ0-9⁰¹²³⁴⁵⁶⁷⁸⁹%‰°/^×*·().+−-]*)$/iu;
      if (unit && (!scientificUnit.test(compactUnit) && !/^[%‰]$/u.test(unit))) continue;
      candidates.push({name, result: match[1].trim(), unit});
    }
    if (candidates.length !== 1) return emptyRow(sourceLine, 'Не удалось однозначно разделить строку. Заполните поля вручную по оригиналу.');
    Object.assign(row, candidates[0]);
    if (/\s\d|[:;|\t]/u.test(row.name)) {
      return emptyRow(sourceLine, 'В строке несколько возможных значений. Заполните поля вручную по оригиналу.');
    }
    if (row.unit && /^[a-zа-яёµμ]+$/iu.test(row.unit)) {
      row.warnings.push('Проверьте единицу измерения: скопировано слово после результата.');
    }
    return row;
  }

  function parse(text) {
    if (typeof text !== 'string') throw new TypeError('Вставьте результаты в виде текста.');
    if (text.length > MAX_TEXT_LENGTH) throw new RangeError(`Вставьте не более ${MAX_TEXT_LENGTH} символов за один раз.`);
    if (text.includes('\0')) throw new TypeError('Текст содержит недопустимый нулевой символ. Вставьте обычный текст.');
    const lines = text.split(/\r\n|\n|\r/u);
    if (lines.at(-1) === '') lines.pop();
    if (lines.length > MAX_ROWS) throw new RangeError(`Вставьте не более ${MAX_ROWS} строк за один раз.`);
    const rows = [], notices = [];
    let mapping = null;
    let blankCount = 0;
    for (const sourceLine of lines) {
      if (!sourceLine.trim()) { blankCount += 1; continue; }
      const split = columns(sourceLine);
      if (!split) { rows.push(parseSimple(sourceLine)); continue; }
      const cells = split.cells.map(cell => cell.trim());
      const names = cells.map(headerField);
      const named = names.filter(Boolean);
      if (named.includes('name') || (named.includes('result') && named.length > 1)) {
        const valid = named.includes('name') && named.includes('result') && named.length === cells.length && new Set(named).size === named.length;
        if (valid) {
          mapping = {kind: split.kind, names};
          notices.push(`Заголовок столбцов пропущен: ${sourceLine}`);
        } else {
          mapping = {kind: split.kind, names: null};
          rows.push(emptyRow(sourceLine, 'Не все заголовки столбцов распознаны. Заполните строки этой таблицы вручную.'));
        }
        continue;
      }
      if (mapping?.kind === split.kind && !mapping.names) {
        rows.push(emptyRow(sourceLine, 'Порядок столбцов не распознан. Заполните поля вручную по оригиналу.'));
        continue;
      }
      const order = mapping?.kind === split.kind ? mapping.names : fields;
      const row = emptyRow(sourceLine);
      order.forEach((field, index) => { row[field] = cells[index] || ''; });
      if (cells.length > order.length) row.warnings.push('Есть дополнительные столбцы. Их содержимое сохранено в исходной строке; перенесите нужное вручную.');
      if (mapping?.kind === split.kind && cells.length !== order.length) row.warnings.push('Количество столбцов отличается от заголовка. Проверьте распределение значений.');
      if (!row.name || !row.result) row.warnings.push('Название или результат не заполнены. Проверьте исходную строку.');
      rows.push(row);
    }
    if (blankCount) notices.push(`Пропущено пустых строк: ${blankCount}.`);
    return {rows, notices};
  }

  return Object.freeze({parse, MAX_TEXT_LENGTH, MAX_ROWS});
})();

/* Generated offline ICD catalog. Rebuild with node release/build-icd.cjs. */
window.MedAssistICDReady = (async function () {
  const bytes = Uint8Array.from(atob(""), character => character.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  const catalog = await new Response(stream).json();
  const createLookup = function createLookup(catalog) {
  if (!catalog || typeof catalog !== "object" || Array.isArray(catalog)) {
    throw new TypeError("ICD catalog must be an object");
  }
  if (!catalog.metadata || typeof catalog.metadata !== "object" || Array.isArray(catalog.metadata)) {
    throw new TypeError("ICD catalog metadata must be an object");
  }
  const metadata = {};
  for (const key of ["classification", "release", "publisher", "sourceUrl", "checkedAt", "note"]) {
    const value = catalog.metadata[key];
    if (typeof value !== "string" || (key !== "note" && !value.trim())) {
      throw new TypeError(`ICD catalog metadata.${key} must be a${key === "note" ? "" : " non-empty"} string`);
    }
    metadata[key] = value;
  }
  Object.freeze(metadata);
  if (!Array.isArray(catalog.entries)) throw new TypeError("ICD catalog entries must be an array");

  function normalize(value) {
    return value.normalize("NFKC").toLowerCase().replace(/ё/g, "е").replace(/\s+/g, " ").trim();
  }
  function words(value) {
    return value.match(/[a-zа-я0-9]+(?:\.[0-9]+[a-z]?)?/g) || [];
  }
  function stem(value) {
    const shortened = value.replace(/(?:ыми|ими|ого|его|ому|ему|ый|ий|ой|ая|яя|ое|ее|ые|ие|ых|их|ую|юю|ым|им|ом|ем)$/, "");
    return shortened.length >= 3 ? shortened : value;
  }

  const codes = new Set();
  const indexed = catalog.entries.map((source, index) => {
    const label = `ICD catalog entry ${index}`;
    if (!source || typeof source !== "object" || Array.isArray(source)) throw new TypeError(`${label} must be an object`);
    if (typeof source.code !== "string" || !/^[A-Z][0-9]{2}(?:\.[0-9]{1,4})?[A-Z]?$/.test(source.code)) {
      throw new TypeError(`${label} has an invalid code`);
    }
    if (codes.has(source.code)) throw new TypeError(`${label} has duplicate code ${source.code}`);
    codes.add(source.code);
    if (typeof source.title !== "string" || !source.title.trim()) throw new TypeError(`${label} must have a non-empty title`);
    if (source.kind !== "category" && source.kind !== "subcategory") throw new TypeError(`${label} has an invalid kind`);
    if ((source.kind === "subcategory") !== source.code.includes(".")) throw new TypeError(`${label} kind does not match its code`);
    if (source.aliases !== undefined && (!Array.isArray(source.aliases) || source.aliases.some(alias => typeof alias !== "string" || !alias.trim()))) {
      throw new TypeError(`${label} aliases must be non-empty strings`);
    }
    if (source.parent !== undefined && (!source.parent || typeof source.parent !== "object" || Array.isArray(source.parent) ||
      typeof source.parent.code !== "string" || !source.parent.code.trim() || typeof source.parent.title !== "string" || !source.parent.title.trim())) {
      throw new TypeError(`${label} parent must contain non-empty code and title strings`);
    }
    const entry = {code: source.code, title: source.title, kind: source.kind};
    if (source.aliases !== undefined) entry.aliases = Object.freeze([...source.aliases]);
    if (source.parent !== undefined) entry.parent = Object.freeze({code: source.parent.code, title: source.parent.title});
    Object.freeze(entry);
    const title = normalize(entry.title);
    const aliases = (entry.aliases || []).map(normalize);
    const tokens = [...new Set([title, ...aliases].flatMap(words))];
    return {entry, code: entry.code.toLowerCase(), title, aliases, phrases: [title, ...aliases].map(value => ` ${words(value).join(" ")} `), tokens, stems: tokens.map(stem)};
  });
  const empty = Object.freeze({items: Object.freeze([]), total: 0});

  function search(query, limit = 20) {
    if (typeof query !== "string") throw new TypeError("ICD search query must be a string");
    if (!Number.isInteger(limit) || limit < 1) throw new RangeError("ICD search limit must be a positive integer");
    const count = Math.min(limit, 50);
    const normalized = normalize(query);
    const terms = words(normalized);
    if (terms.join("").replace(/\./g, "").length < 2) return empty;
    const stems = terms.map(stem);
    const codePattern = /^[a-z][0-9]{1,2}(?:\.[0-9]{0,4})?[a-z]?$/;
    const codeQuery = codePattern.test(normalized) ? normalized : terms.length === 1 && codePattern.test(terms[0]) ? terms[0] : null;
    const phrase = ` ${terms.join(" ")} `;
    const matches = [];
    for (const item of indexed) {
      if (codeQuery && !item.code.startsWith(codeQuery)) continue;
      const literal = terms.every(term => item.code.startsWith(term) || item.tokens.some(token => token.startsWith(term)));
      if (!literal && !terms.every((term, i) => item.code.startsWith(term) || item.tokens.some(token => token.startsWith(term)) || item.stems.some(token => token.startsWith(stems[i])))) continue;
      let rank;
      if (item.code === (codeQuery || normalized)) rank = 0;
      else if (item.title === normalized) rank = 1;
      else if (item.aliases.includes(normalized)) rank = 2;
      else if (item.phrases[0].includes(phrase)) rank = 3;
      else if (item.phrases.slice(1).some(value => value.includes(phrase))) rank = 4;
      else if (item.code.startsWith(normalized)) rank = 5;
      else rank = literal ? 6 : 7;
      matches.push({entry: item.entry, rank});
    }
    matches.sort((a, b) => a.rank - b.rank || (a.entry.code < b.entry.code ? -1 : a.entry.code > b.entry.code ? 1 : 0));
    return Object.freeze({items: Object.freeze(matches.slice(0, count).map(item => item.entry)), total: matches.length});
  }

  return Object.freeze({metadata, size: indexed.length, search});
};
  return createLookup(catalog);
})();
